const gameUpgrades=JSON.parse(localStorage.getItem('blockverse-upgrades')||'{}');function upgradeLevel(name){return gameUpgrades[name]||0}function saveUpgrades(){localStorage.setItem('blockverse-upgrades',JSON.stringify(gameUpgrades))}
