function difficulty(game){return state.levels[game]||1}function win(game){const beaten=difficulty(game);state.levels[game]=beaten+1;localStorage.setItem('blockverse-levels',JSON.stringify(state.levels));if(!state.done.has(game)){state.done.add(game);localStorage.setItem('game-within',JSON.stringify([...state.done]));$('#toast').textContent='POWER CUBE EARNED!';$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2200)}beep(880,.2);update();stage.innerHTML=`<div class="game-ui"><p class="eyebrow">LEVEL ${beaten} COMPLETE</p><h2>LEVEL ${beaten+1} UNLOCKED!</h2><p>The next round is harder. Your Power Cube is active.</p><button class="primary" onclick="closeGame()">BACK TO GAMES</button></div>`}
function showAvatarInGame(){const old=stage.querySelector('.game-avatar');if(old)old.remove();const source=document.querySelector('.avatar-preview .player-avatar');if(source){const clone=source.cloneNode(true);clone.classList.add('game-avatar');stage.append(clone)}}function openGame(game){const numbers={memory:'01',react:'02',dodge:'03',coins:'04',math:'05',target:'06',obby2:'07',stars:'08',emoji:'09',rhythm:'10',survival:'12',forest:'13',squishy:'14',soloobby:'15',builder:'16',moondash:'17',petrescue:'18',pizzapop:'19',bubblepop:'20',gemhunt:'21',fashionrun:'22',fishing:'23',snowball:'24',cakestack:'25',spaceminer:'26'},games={memory:memoryGame,react:reactGame,dodge:dodgeGame,coins:coinGame,math:mathGame,target:targetGame,obby2:twoPlayerObby,stars:starGame,emoji:emojiGame,rhythm:rhythmGame,survival:survivalGame,forest:forestGame,squishy:squishyGame,soloobby:soloObbyGame,builder:builderGame};if(!numbers[game])return;state.game=game;modal.classList.add('open');modal.setAttribute('aria-hidden','false');$('#gameNumber').textContent='GAME '+numbers[game];(games[game]||(()=>quickArcadeGame(game)))();showAvatarInGame()}
function closeGame(){if(gameCleanup){gameCleanup();gameCleanup=null}modal.classList.remove('open');modal.setAttribute('aria-hidden','true');stage.innerHTML='';state.game=null}
