function memoryGame(){let seq=[],input=[],level=1,busy=false;stage.innerHTML=`<div class="game-ui"><p class="eyebrow">// GHOST SIGNAL</p><h2>REPEAT THE PATTERN</h2><p id="memoryMsg">Reach sequence level 5.</p><div class="pads">${[0,1,2,3].map(i=>`<button class="pad" data-pad="${i}"></button>`).join('')}</div><button class="primary" id="memoryStart">START SIGNAL</button></div>`;const pads=$$('.pad');async function flash(i){pads[i].classList.add('lit');beep(260+i*130);await new Promise(r=>setTimeout(r,380));pads[i].classList.remove('lit');await new Promise(r=>setTimeout(r,100))}async function round(){busy=true;input=[];seq.push(Math.floor(Math.random()*4));$('#memoryMsg').textContent=`LEVEL ${level} — WATCH`;await new Promise(r=>setTimeout(r,450));for(const i of seq)await flash(i);busy=false;$('#memoryMsg').textContent=`LEVEL ${level} — YOUR TURN`}pads.forEach((p,i)=>p.onclick=async()=>{if(busy||!seq.length)return;await flash(i);input.push(i);const n=input.length-1;if(input[n]!==seq[n]){seq=[];level=1;$('#memoryMsg').textContent='SIGNAL LOST — TRY AGAIN';beep(90,.25);return}if(input.length===seq.length){level++;if(level>5)return win('memory');busy=true;setTimeout(round,600)}});$('#memoryStart').onclick=()=>{if(!busy){seq=[];level=1;round()}}}
function reactGame(){stage.innerHTML=`<div class="game-ui"><p class="eyebrow">// VOID TRIGGER</p><h2>WAIT FOR THE ANOMALY</h2><p id="reactMsg">Three clean hits to win.</p><div class="react-zone" id="reactZone">CLICK TO ARM</div></div>`;let armed=false,go=false,hits=0,timer,start;const zone=$('#reactZone');function arm(){if(armed)return;armed=true;go=false;zone.classList.remove('go');zone.textContent='WAIT...';timer=setTimeout(()=>{go=true;start=performance.now();zone.classList.add('go');zone.textContent='HIT NOW';beep(700)},1200+Math.random()*2500)}zone.onclick=()=>{if(!armed){arm();return}if(!go){clearTimeout(timer);armed=false;zone.textContent='TOO EARLY — CLICK TO REARM';beep(80,.2);return}const ms=Math.round(performance.now()-start);hits++;armed=false;go=false;zone.classList.remove('go');$('#reactMsg').textContent=`HIT ${hits}/3 — ${ms}ms`;if(hits===3)return win('react');zone.textContent='CLICK TO ARM';beep(450+hits*100)}}
function dodgeGame(){stage.innerHTML=`<div class="game-ui"><p class="eyebrow">// LAST DRIFTER</p><h2>SURVIVE 12 SECONDS</h2><p id="dodgeMsg">Use ← → or drag your pointer.</p><div class="dodge-board" id="board"><div class="player" id="player"></div></div><button class="primary" id="dodgeStart">LAUNCH</button></div>`;const board=$('#board'),player=$('#player');let x=196,running=false,rocks=[],start,lastSpawn=0,raf;function pos(){player.style.left=x+'px'}pos();function move(clientX){const r=board.getBoundingClientRect();x=Math.max(0,Math.min(r.width-28,clientX-r.left-14));pos()}board.onpointermove=e=>{if(running)move(e.clientX)};function key(e){if(!running)return;if(e.key==='ArrowLeft')x=Math.max(0,x-24);if(e.key==='ArrowRight')x=Math.min(board.clientWidth-28,x+24);pos()}document.addEventListener('keydown',key,{signal:new AbortController().signal});function loop(t){if(!running)return;const elapsed=(t-start)/1000;$('#dodgeMsg').textContent=`${Math.max(0,12-elapsed).toFixed(1)} SECONDS`;if(elapsed>=12){running=false;return win('dodge')}if(t-lastSpawn>420){const el=document.createElement('i');el.className='rock';const rx=Math.random()*(board.clientWidth-24);el.style.left=rx+'px';el.style.top='-30px';board.append(el);rocks.push({el,x:rx,y:-30});lastSpawn=t}for(const r of rocks){r.y+=4.5;r.el.style.top=r.y+'px';if(r.y>board.clientHeight)r.el.remove();if(r.y+24>board.clientHeight-46&&r.y<board.clientHeight-16&&r.x+24>x&&r.x<x+28){running=false;rocks.forEach(o=>o.el.remove());$('#dodgeMsg').textContent='IMPACT — LAUNCH AGAIN';$('#dodgeStart').disabled=false;beep(70,.3);return}}rocks=rocks.filter(r=>r.y<board.clientHeight);raf=requestAnimationFrame(loop)}$('#dodgeStart').onclick=e=>{rocks.forEach(r=>r.el.remove());rocks=[];running=true;e.currentTarget.disabled=true;start=performance.now();lastSpawn=start;raf=requestAnimationFrame(loop)}}
function coinGame(){stage.innerHTML=`<div class="game-ui"><p class="eyebrow">COIN RUSH</p><h2>GRAB 10 COINS</h2><p id="coinMsg">10 seconds left · 0 / 10</p><div class="coin-field" id="coinField"></div><button class="primary" id="coinStart">START</button></div>`;let score=0,time=10,tick;const field=$('#coinField'),msg=$('#coinMsg');function spawn(){field.innerHTML='';const c=document.createElement('button');c.className='coin';c.textContent='★';c.style.left=Math.random()*(field.clientWidth-50)+'px';c.style.top=Math.random()*(field.clientHeight-50)+'px';c.onclick=()=>{score++;beep(500+score*25);if(score>=10){clearInterval(tick);return win('coins')}msg.textContent=`${time} seconds left · ${score} / 10`;spawn()};field.append(c)}$('#coinStart').onclick=e=>{score=0;time=10;e.currentTarget.style.display='none';spawn();tick=setInterval(()=>{time--;msg.textContent=`${time} seconds left · ${score} / 10`;if(time<=0){clearInterval(tick);field.innerHTML='';msg.textContent='TIME UP — TRY AGAIN';e.currentTarget.style.display='inline-block'}},1000)}}
function mathGame(){let round=0,answer=0;stage.innerHTML=`<div class="game-ui"><p class="eyebrow">MATH MAYHEM</p><h2 id="sum">READY?</h2><p id="mathMsg">Solve five in a row.</p><div class="answers" id="answers"></div><button class="primary" id="mathStart">START</button></div>`;function next(){const a=2+Math.floor(Math.random()*18),b=2+Math.floor(Math.random()*18);answer=a+b;$('#sum').textContent=`${a} + ${b} = ?`;const choices=[answer,answer+1+Math.floor(Math.random()*3),Math.max(1,answer-1-Math.floor(Math.random()*3)),answer+4+Math.floor(Math.random()*4)].sort(()=>Math.random()-.5);$('#answers').innerHTML=choices.map(n=>`<button class="answer">${n}</button>`).join('');$$('.answer').forEach(btn=>btn.onclick=()=>{if(+btn.textContent!==answer){round=0;beep(80,.2);$('#mathMsg').textContent='OOPS! STREAK RESET';return next()}round++;beep(600);if(round===5)return win('math');$('#mathMsg').textContent=`${round} / 5 CORRECT`;next()})}$('#mathStart').onclick=e=>{e.currentTarget.remove();next()}}
function awardMoonGems(amount){amount+=upgradeLevel('rewards');avatarData.moonGems+=amount;paintAvatar();const reward=document.createElement('div');reward.className='moon-reward';reward.innerHTML=`<div><b>🌙 +${amount}</b><span>MOON GEMS EARNED!</span></div>`;document.body.append(reward);setTimeout(()=>reward.remove(),2400)}
function targetGame(){stage.innerHTML=`<div class="game-ui"><p class="eyebrow">TARGET SMASH</p><h2>HIT 8 TARGETS</h2><p id="targetMsg">Win to earn 3 Moon Gems.</p><div class="target-field" id="targetField"></div><button class="primary" id="targetStart">START</button></div>`;let hits=0;const field=$('#targetField'),msg=$('#targetMsg');function spawn(){field.innerHTML='';const t=document.createElement('button');t.className='moving-target';t.style.left=Math.random()*(field.clientWidth-62)+'px';t.style.top=Math.random()*(field.clientHeight-62)+'px';t.onclick=()=>{hits++;beep(420+hits*40);msg.textContent=`${hits} / 8 HITS`;if(hits===8){awardMoonGems(3);return win('target')}spawn()};field.append(t)}$('#targetStart').onclick=e=>{hits=0;e.currentTarget.remove();spawn()}}
function twoPlayerObby(){stage.innerHTML=`<div class="game-ui"><p class="eyebrow">LOCAL TWO PLAYER</p><h2>DUO OBBY</h2><div class="obby-controls"><span>PLAYER 1: W A S D</span><span>PLAYER 2: ARROW KEYS</span></div><div class="obby2-board" id="obbyBoard"><div class="obby-finish">BOTH HERE!</div><i class="obby-platform" style="left:90px;top:255px;width:300px"></i><i class="obby-platform" style="left:0;top:175px;width:310px"></i><i class="obby-platform" style="left:185px;top:95px;width:335px"></i><div class="obby-player p1" id="obbyP1"></div><div class="obby-player p2" id="obbyP2"></div></div><p id="obbyMsg">Get both players to the yellow finish!</p></div>`;const board=$('#obbyBoard'),els=[$('#obbyP1'),$('#obbyP2')],players=[{x:20,y:295,done:false},{x:55,y:295,done:false}],walls=[{x:90,y:255,w:300,h:18},{x:0,y:175,w:310,h:18},{x:185,y:95,w:335,h:18}];function draw(){players.forEach((p,i)=>{els[i].style.left=p.x+'px';els[i].style.top=p.y+'px'})}function blocked(x,y){return x<0||y<0||x>board.clientWidth-24||y>board.clientHeight-30||walls.some(w=>x+24>w.x&&x<w.x+w.w&&y+30>w.y&&y<w.y+w.h)}function move(i,dx,dy){const p=players[i],nx=p.x+dx,ny=p.y+dy;if(!blocked(nx,ny)){p.x=nx;p.y=ny}if(p.x>board.clientWidth-90&&p.y<55)p.done=true;draw();$('#obbyMsg').textContent=players.map((q,j)=>`P${j+1}: ${q.done?'FINISHED':'RUNNING'}`).join(' · ');if(players.every(q=>q.done)){document.removeEventListener('keydown',keys);gameCleanup=null;awardMoonGems(2);stage.innerHTML=`<div class="game-ui"><p class="eyebrow">TEAM VICTORY</p><h2>BOTH PLAYERS WIN!</h2><p>Perfect teamwork. You earned 2 Moon Gems.</p><button class="primary" onclick="closeGame()">BACK TO ARCADE</button></div>`}}function keys(e){const map={w:[0,0,-12],s:[0,0,12],a:[0,-12,0],d:[0,12,0],ArrowUp:[1,0,-12],ArrowDown:[1,0,12],ArrowLeft:[1,-12,0],ArrowRight:[1,12,0]};if(map[e.key]){e.preventDefault();move(...map[e.key])}}document.addEventListener('keydown',keys);gameCleanup=()=>document.removeEventListener('keydown',keys);draw()}
function bonusWin(game){const beaten=difficulty(game);state.levels[game]=beaten+1;localStorage.setItem('blockverse-levels',JSON.stringify(state.levels));awardMoonGems(1);stage.innerHTML=`<div class="game-ui"><p class="eyebrow">LEVEL ${beaten} COMPLETE</p><h2>AMAZING!</h2><p>Level ${beaten+1} is now harder. You also earned 1 Moon Gem.</p><button class="primary" onclick="closeGame()">BACK TO ARCADE</button></div>`}
function survivalGame(){const level=difficulty('survival'),duration=18+level*2;stage.innerHTML=`<div class="game-ui"><p class="eyebrow">NIGHT ESCAPE <span class="level-badge">LEVEL ${level}</span></p><h2>SURVIVE THE NIGHT</h2><div class="survival-hud"><span id="survivalHp">❤️❤️❤️</span><span id="survivalTime">${duration}s</span></div><div class="survival-board" id="survivalBoard"><div class="survivor" id="survivor"></div></div><p>Move with W A S D or arrow keys.</p></div>`;const board=$('#survivalBoard'),hero=$('#survivor');let x=board.clientWidth/2,y=board.clientHeight/2,hp=3,enemies=[],running=true,lastSpawn=0,start=performance.now(),lastHit=0;function draw(){hero.style.left=x+'px';hero.style.top=y+'px'}function key(e){const speed=15,map={w:[0,-speed],s:[0,speed],a:[-speed,0],d:[speed,0],ArrowUp:[0,-speed],ArrowDown:[0,speed],ArrowLeft:[-speed,0],ArrowRight:[speed,0]};if(map[e.key]){e.preventDefault();x=Math.max(0,Math.min(board.clientWidth-30,x+map[e.key][0]));y=Math.max(0,Math.min(board.clientHeight-30,y+map[e.key][1]));draw()}}function spawn(){const el=document.createElement('i');el.className='shadow-enemy';const side=Math.floor(Math.random()*4),p={el,x:side===0?0:side===1?board.clientWidth-26:Math.random()*board.clientWidth,y:side===2?0:side===3?board.clientHeight-26:Math.random()*board.clientHeight};board.append(el);enemies.push(p)}function loop(t){if(!running)return;const elapsed=(t-start)/1000,left=Math.max(0,duration-elapsed);$('#survivalTime').textContent=Math.ceil(left)+'s';if(left<=0){running=false;document.removeEventListener('keydown',key);gameCleanup=null;return bonusWin('survival')}if(t-lastSpawn>Math.max(380,1150-level*90)){spawn();lastSpawn=t}for(const e of enemies){const dx=x-e.x,dy=y-e.y,d=Math.hypot(dx,dy)||1,speed=1.1+level*.12;e.x+=dx/d*speed;e.y+=dy/d*speed;e.el.style.left=e.x+'px';e.el.style.top=e.y+'px';if(Math.abs(e.x-x)<25&&Math.abs(e.y-y)<25&&t-lastHit>900){hp--;lastHit=t;$('#survivalHp').textContent='❤️'.repeat(hp)+'🖤'.repeat(3-hp);beep(80,.25);if(hp<=0){running=false;document.removeEventListener('keydown',key);gameCleanup=null;stage.innerHTML=`<div class="game-ui"><h2>THE SHADOWS GOT YOU</h2><p>Keep moving and try again.</p><button class="primary" onclick="survivalGame()">RETRY LEVEL ${level}</button></div>`;return}}}requestAnimationFrame(loop)}document.addEventListener('keydown',key);gameCleanup=()=>{running=false;document.removeEventListener('keydown',key)};draw();requestAnimationFrame(loop)}
function starGame(){const level=difficulty('stars'),goal=8+level*2;stage.innerHTML=`<div class="game-ui"><p class="eyebrow">STAR CATCHER <span class="level-badge">LEVEL ${level}</span></p><h2>CATCH ${goal} STARS</h2><p id="starMsg">Use ← → or move your pointer. Avoid ☄!</p><div class="catch-board" id="catchBoard"><div class="catcher" id="catcher"></div></div></div>`;const board=$('#catchBoard'),catcher=$('#catcher');let x=195,score=0,items=[],last=0,running=true;function setX(n){x=Math.max(0,Math.min(board.clientWidth-70,n));catcher.style.left=x+'px'}function keys(e){if(e.key==='ArrowLeft')setX(x-28);if(e.key==='ArrowRight')setX(x+28)}document.addEventListener('keydown',keys);board.onpointermove=e=>setX(e.clientX-board.getBoundingClientRect().left-35);function loop(t){if(!running)return;if(t-last>Math.max(350,700-level*35)){const el=document.createElement('i'),bad=Math.random()<.22;el.className='falling';el.textContent=bad?'☄':'★';el.dataset.bad=bad;el.style.left=Math.random()*(board.clientWidth-35)+'px';el.style.top='-30px';board.append(el);items.push({el,x:parseFloat(el.style.left),y:-30,bad});last=t}for(const o of items){o.y+=3+level*.35;o.el.style.top=o.y+'px';if(o.y>245&&o.y<300&&o.x+28>x&&o.x<x+70){o.el.remove();o.y=999;if(o.bad){score=Math.max(0,score-2);beep(80,.2)}else{score++;beep(600);if(score>=goal){running=false;document.removeEventListener('keydown',keys);gameCleanup=null;return bonusWin('stars')}}$('#starMsg').textContent=`${score} / ${goal} STARS`}if(o.y>300)o.el.remove()}items=items.filter(o=>o.y<300);requestAnimationFrame(loop)}gameCleanup=()=>{running=false;document.removeEventListener('keydown',keys)};setX(x);requestAnimationFrame(loop)}
function emojiGame(){const level=difficulty('emoji'),icons=['🌸','🍓','🐰','⭐','🍡','🦋'].slice(0,Math.min(6,3+level)),cards=[...icons,...icons].sort(()=>Math.random()-.5);let open=[],matched=0,locked=false;stage.innerHTML=`<div class="game-ui"><p class="eyebrow">KAWAII PAIRS <span class="level-badge">LEVEL ${level}</span></p><h2>MATCH THE PAIRS</h2><p id="pairMsg">Find ${icons.length} matching pairs.</p><div class="match-grid" style="grid-template-columns:repeat(${icons.length>4?4:3},70px)">${cards.map((x,i)=>`<button class="match-card" data-card="${i}">${x}</button>`).join('')}</div></div>`;$$('.match-card').forEach(b=>b.onclick=()=>{if(locked||b.classList.contains('open')||b.classList.contains('matched'))return;b.classList.add('open');open.push(b);if(open.length===2){locked=true;if(open[0].textContent===open[1].textContent){open.forEach(x=>x.classList.add('matched'));matched++;open=[];locked=false;beep(650);if(matched===icons.length)bonusWin('emoji')}else setTimeout(()=>{open.forEach(x=>x.classList.remove('open'));open=[];locked=false;beep(110)},650)}})}
function rhythmGame(){const level=difficulty('rhythm'),goal=10+level*2,keys=['d','f','j','k'];let active=-1,hits=0,running=true,timer;stage.innerHTML=`<div class="game-ui"><p class="eyebrow">BEAT POP <span class="level-badge">LEVEL ${level}</span></p><h2>FOLLOW THE BEAT</h2><p id="beatMsg">Press D F J K when a lane glows · 0/${goal}</p><div class="beat-board"><div class="beat-lanes">${keys.map(k=>`<div class="beat-lane"><div class="beat-key">${k.toUpperCase()}</div></div>`).join('')}</div></div></div>`;const lanes=$$('.beat-lane');function next(){lanes.forEach(x=>x.classList.remove('go'));active=Math.floor(Math.random()*4);lanes[active].classList.add('go')}function press(e){const i=keys.indexOf(e.key.toLowerCase());if(i<0||!running)return;if(i===active){hits++;beep(440+i*90);$('#beatMsg').textContent=`PERFECT! · ${hits}/${goal}`;if(hits>=goal){running=false;clearInterval(timer);document.removeEventListener('keydown',press);gameCleanup=null;return bonusWin('rhythm')}next()}else{$('#beatMsg').textContent=`MISS! · ${hits}/${goal}`;beep(90)}}document.addEventListener('keydown',press);timer=setInterval(next,Math.max(380,900-level*45));gameCleanup=()=>{running=false;clearInterval(timer);document.removeEventListener('keydown',press)};next()}
function updateTreasure(){const btn=$('#openChest');if(!btn)return;const opened=localStorage.getItem('treasure-opened')==='yes',ready=state.done.size>=6;btn.disabled=!ready||opened;btn.textContent=opened?'✓ TREASURE CLAIMED':ready?'OPEN RANDOM TREASURE':`${state.done.size} / 6 POWER CUBES`;const history=localStorage.getItem('treasure-prize');if(history)$('#rewardHistory').textContent=`LAST PRIZE: ${history}`}
$('#openChest').onclick=()=>{if(state.done.size<6||localStorage.getItem('treasure-opened'))return;const prizes=[{icon:'🌙',name:'10 Moon Gems',run:()=>avatarData.moonGems+=10},{icon:'🌙✨',name:'25 Moon Gems',run:()=>avatarData.moonGems+=25},{icon:'🌙💫',name:'50 Moon Gems',run:()=>avatarData.moonGems+=50},{icon:'♛',name:'Golden Crown',run:()=>{if(!avatarData.owned.includes('crown'))avatarData.owned.push('crown')}},{icon:'👕',name:'Treasure Glow Shirt',run:()=>{clothingDesigns.push({id:Date.now(),name:'Treasure Glow',main:'#ffd429',second:'#855cff',pattern:'stripes'});saveClothes()}},{icon:'👖',name:'Legendary Star Pants',run:()=>{pantsDesigns.push({id:Date.now(),name:'Legendary Stars',main:'#25204f',second:'#ffd429',pattern:'checker'});savePants()}}],prize=prizes[Math.floor(Math.random()*prizes.length)];prize.run();localStorage.setItem('treasure-opened','yes');localStorage.setItem('treasure-prize',prize.name);paintAvatar();renderClothes();renderPants();$('#treasureChest').classList.add('open');const burst=document.createElement('div');burst.className='prize-burst';burst.innerHTML=`<div><b>${prize.icon}</b><h2>${prize.name}</h2><p>Random treasure unlocked!</p></div>`;document.body.append(burst);setTimeout(()=>burst.remove(),3000);update();beep(1000,.35)};
