function dancePartyGame(){modal.classList.add('open');modal.setAttribute('aria-hidden','false');$('#gameNumber').textContent='DANCE PARTY · 4 CUBES';let round=0,index=0,sequence=[],timeLeft=45,timer=null,playing=true;const names=['WARM-UP MOVES','DISCO DASH','FREEZE BEAT','FINAL COMBO'],icons={ArrowUp:'⬆️',ArrowDown:'⬇️',ArrowLeft:'⬅️',ArrowRight:'➡️'},moves=Object.keys(icons);function clock(){const el=$('#danceTimer');if(el)el.textContent=`⏱ ${timeLeft}s`;if(timeLeft<=10&&el)el.classList.add('danger')}function build(){if(!playing)return;const length=4+round*2;sequence=Array.from({length},()=>moves[Math.floor(Math.random()*4)]);index=0;stage.innerHTML=`<div class="game-ui"><p class="eyebrow">DANCE MINI-GAME ${round+1} / 4</p><div class="dance-timer" id="danceTimer">⏱ ${timeLeft}s</div><h2>${names[round]}</h2><div class="dance-progress">${[0,1,2,3].map(i=>`<i class="${i<round?'done':i===round?'active':''}"></i>`).join('')}</div><div class="dance-stage"><div class="dance-floor"></div><div class="dance-prompt"><b>${sequence.map(x=>icons[x]).join(' ')}</b><span id="danceMsg">USE THE ARROW KEYS · 0/${length}</span></div></div></div>`;showAvatarInGame();clock()}function press(e){if(!playing||!moves.includes(e.key))return;e.preventDefault();if(e.key===sequence[index]){index++;beep(420+index*35);$('#danceMsg').textContent=`PERFECT · ${index}/${sequence.length}`;if(index===sequence.length){round++;if(round===4)return finish();setTimeout(build,600)}}else{index=0;beep(80,.2);$('#danceMsg').textContent='MISSED! START THIS COMBO AGAIN'}}function stop(){playing=false;clearInterval(timer);document.removeEventListener('keydown',press)}function lose(){stop();gameCleanup=null;stage.innerHTML=`<div class="game-ui dance-card-win"><p class="eyebrow">TIME IS UP</p><h2>⏱ DANCE OVER!</h2><p>Complete all four combos before the 45-second timer reaches zero.</p><button class="primary" onclick="dancePartyGame()">TRY AGAIN</button></div>`;beep(80,.35)}function finish(){stop();gameCleanup=null;const claimed=localStorage.getItem('dance-party-prize')==='yes',prize=claimed?10:100;avatarData.moonGems+=prize;paintAvatar();if(!claimed)localStorage.setItem('dance-party-prize','yes');stage.innerHTML=`<div class="game-ui dance-card-win"><p class="eyebrow">ALL 4 MINI-GAMES COMPLETE · ${timeLeft}s LEFT</p><h2>🪩 PARTY CHAMPION!</h2><p>You earned ${prize} Moon Gems${claimed?' for your replay':' — the grand prize'}!</p><button class="primary" onclick="closeGame()">COLLECT PRIZE</button></div>`;beep(980,.3)}document.addEventListener('keydown',press);timer=setInterval(()=>{timeLeft--;clock();if(timeLeft<=0)lose()},1000);gameCleanup=stop;build()}
