$('#duelBtn').onclick=()=>{if(state.done.size){duelGame();showAvatarInGame()}};
function duelGame(){modal.classList.add('open');modal.setAttribute('aria-hidden','false');$('#gameNumber').textContent='POWER CUBE DUEL';const maxPlayer=3+state.done.size,maxBot=5;let player=maxPlayer,bot=maxBot,busy=false;stage.innerHTML=`<div class="battlefield"><p class="eyebrow">DUEL ARENA · ${state.done.size} POWER CUBES ACTIVE</p><div class="battle-hud"><div class="battle-player"><h3>YOU</h3><span id="playerHp">${player} / ${maxPlayer} HP</span><div class="health-track"><i id="playerHealth"></i></div></div><b>VS</b><div class="battle-bot"><h3>BLOCK BOT</h3><span id="botHp">${bot} / ${maxBot} HP</span><div class="health-track"><i id="botHealth"></i></div></div></div><div class="battle-log" id="battleLog"><b>◆</b><p>Choose your first move.</p></div><div class="battle-actions"><button data-move="attack">⚔️ ATTACK</button><button data-move="guard">🛡️ GUARD</button><button data-move="charge">⚡ CHARGE</button></div></div>`;const icons={attack:'⚔️',guard:'🛡️',charge:'⚡'},wins={attack:'charge',guard:'attack',charge:'guard'},buttons=$$('.battle-actions button');function bars(){$('#playerHp').textContent=`${player} / ${maxPlayer} HP`;$('#botHp').textContent=`${bot} / ${maxBot} HP`;$('#playerHealth').style.width=player/maxPlayer*100+'%';$('#botHealth').style.width=bot/maxBot*100+'%'}function finish(victory){buttons.forEach(b=>b.disabled=true);if(victory){awardMoonGems(2);$('#battleLog').innerHTML='<b>🏆</b><p>DUEL WON! +2 MOON GEMS</p>'}else $('#battleLog').innerHTML='<b>💥</b><p>THE BOT WON — TRY AGAIN</p>';setTimeout(()=>{$('#battleLog').innerHTML+=`<button class="primary" onclick="duelGame()">REMATCH</button>`},700)}buttons.forEach(btn=>btn.onclick=()=>{if(busy)return;busy=true;const move=btn.dataset.move,botMove=['attack','guard','charge'][Math.floor(Math.random()*3)];let message;if(move===botMove)message='Draw — no damage!';else if(wins[move]===botMove){bot--;message='Direct hit! Bot loses 1 HP.';beep(650)}else{player--;message='The bot hits! You lose 1 HP.';beep(120)}$('#battleLog').innerHTML=`<b>${icons[move]} ${icons[botMove]}</b><p>${message}</p>`;bars();if(bot<=0)return finish(true);if(player<=0)return finish(false);setTimeout(()=>{busy=false;$('#battleLog').innerHTML='<b>◆</b><p>Choose your next move.</p>'},650)})}
