function renderCreatedGames(){const grid=$('#communityGames');grid.innerHTML=createdGames.map((g,i)=>`<article class="cabinet community-card" style="--accent:${g.color}"><button class="delete-game" data-delete="${i}" title="Delete game">×</button><div class="cabinet-top"><span>PLAYER MADE</span></div><div class="game-art" style="--accent:${g.color}"><b>${g.type==='click'?'👆':g.type==='guess'?'❓':'💎'}</b></div><p class="genre">${g.type.toUpperCase()} · NEW</p><h3>${g.name.replace(/</g,'&lt;')}</h3><p>Created in Blockverse Studio.</p><button class="play-created" data-created="${i}">PLAY <span>▶</span></button></article>`).join('');$$('.play-created').forEach(b=>b.onclick=()=>playCreated(createdGames[+b.dataset.created]));$$('.delete-game').forEach(b=>b.onclick=()=>{createdGames.splice(+b.dataset.delete,1);saveCreated();renderCreatedGames()})}
