function createdGuess(g){const secret=1+Math.floor(Math.random()*20);stage.innerHTML=`<div class="game-ui" style="--game-color:${g.color}"><p class="eyebrow">${g.name}</p><h2>NUMBER QUEST</h2><p id="guessMsg">Guess a number from 1 to 20.</p><input class="guess-input" id="guessInput" type="number" min="1" max="20"><button class="primary" id="guessBtn">GUESS</button></div>`;$('#guessBtn').onclick=()=>{const n=+$('#guessInput').value;if(n===secret)return createdWin(g.name);$('#guessMsg').textContent=n<secret?'Too low — go higher!':'Too high — go lower!';beep(120,.1)}}
function createdCollect(g){let count=0,time=12,timer;stage.innerHTML=`<div class="game-ui" style="--game-color:${g.color}"><p class="eyebrow">${g.name}</p><h2>COLLECT 12 GEMS</h2><p id="gemMsg">12 seconds left · 0/12</p><div class="created-game-zone" id="gemField"></div><button class="primary" id="gemStart">START</button></div>`;const field=$('#gemField');function gem(){field.innerHTML='';const x=document.createElement('button');x.className='gem';x.style.left=Math.random()*(field.clientWidth-50)+'px';x.style.top=Math.random()*(field.clientHeight-50)+'px';x.onclick=()=>{count++;beep(500+count*20);if(count===12){clearInterval(timer);return createdWin(g.name)}$('#gemMsg').textContent=`${time} seconds left · ${count}/12`;gem()};field.append(x)}$('#gemStart').onclick=e=>{e.currentTarget.remove();gem();timer=setInterval(()=>{time--;$('#gemMsg').textContent=`${time} seconds left · ${count}/12`;if(time<=0){clearInterval(timer);field.innerHTML='';$('#gemMsg').textContent='TIME UP — CLOSE AND TRY AGAIN'}},1000)}}
