function paintAvatar(){const root=document.documentElement;root.style.setProperty('--skin',avatarData.skin);root.style.setProperty('--shirt',avatarData.shirt);root.style.setProperty('--pants',avatarData.pants);root.style.setProperty('--pants-design',avatarData.pantsDesign?shirtPattern(avatarData.pantsDesign):avatarData.pants);root.style.setProperty('--hair',avatarData.hairColor);root.style.setProperty('--eyes',avatarData.eyeColor);root.style.setProperty('--lips',avatarData.lipColor);root.style.setProperty('--hair-shine',avatarData.hairShine);root.style.setProperty('--shirt-design',avatarData.design?shirtPattern(avatarData.design):avatarData.shirt);$$('.player-avatar').forEach(a=>{a.className=a.className.replace(/\b(accessory|face|hair|makeup|bangs|pants)-(\w+)\b/g,'').replace(/\s+/g,' ').trim();if(avatarData.accessory!=='none')a.classList.add('accessory-'+avatarData.accessory);a.classList.add('face-'+avatarData.face,'hair-'+avatarData.hair,'makeup-'+avatarData.makeup,'bangs-'+avatarData.bangs,'pants-'+avatarData.pantsStyle)});['face','hair','makeup','bangs','pants'].forEach(k=>$$(`[data-${k}]`).forEach(b=>b.classList.toggle('active',b.dataset[k]===avatarData[k==='pants'?'pantsStyle':k])));$('#coinBalance').textContent=avatarData.moonGems;localStorage.setItem('blockverse-avatar',JSON.stringify(avatarData));renderShop()}
