function renderClothes(){$('#myDesigns').innerHTML=clothingDesigns.map((d,i)=>`<article class="design-card ${avatarData.design?.id===d.id?'equipped':''}"><div class="design-swatch" style="background:${shirtPattern(d)}"></div><h4>${d.name.replace(/</g,'&lt;')}</h4><div class="design-actions"><button data-wear="${i}">${avatarData.design?.id===d.id?'WEARING':'EQUIP'}</button><button class="remove-design" data-remove="${i}">×</button></div></article>`).join('');$$('[data-wear]').forEach(b=>b.onclick=()=>{avatarData.design=clothingDesigns[+b.dataset.wear];avatarData.outfit='design';avatarData.shirt=avatarData.design.main;$('#shirtColor').value=avatarData.shirt;paintAvatar();renderClothes();$('#shopNote').textContent='Your custom design is equipped!';beep(720)});$$('[data-remove]').forEach(b=>b.onclick=()=>{const d=clothingDesigns[+b.dataset.remove];if(avatarData.design?.id===d.id){avatarData.design=null;avatarData.outfit='classic';Object.assign(avatarData,shopLooks.classic);paintAvatar()}clothingDesigns.splice(+b.dataset.remove,1);saveClothes();renderClothes()})}
