const pantsDesigns=JSON.parse(localStorage.getItem('blockverse-pants')||'[]');function savePants(){localStorage.setItem('blockverse-pants',JSON.stringify(pantsDesigns))}function renderPants(){$('#myPants').innerHTML=pantsDesigns.map((d,i)=>`<article class="design-card ${avatarData.pantsDesign?.id===d.id?'equipped':''}"><div class="design-swatch" style="background:${shirtPattern(d)}"></div><h4>${safeName(d.name)}</h4><div class="design-actions"><button data-wear-pants="${i}">${avatarData.pantsDesign?.id===d.id?'WEARING':'EQUIP'}</button><button class="remove-design" data-remove-pants="${i}">×</button></div></article>`).join('');$$('[data-wear-pants]').forEach(b=>b.onclick=()=>{avatarData.pantsDesign=pantsDesigns[+b.dataset.wearPants];avatarData.pants=avatarData.pantsDesign.main;avatarData.pantsStyle='jeans';$('#pantsColor').value=avatarData.pants;paintAvatar();renderPants();beep(720)});$$('[data-remove-pants]').forEach(b=>b.onclick=()=>{const d=pantsDesigns[+b.dataset.removePants];if(avatarData.pantsDesign?.id===d.id)avatarData.pantsDesign=null;pantsDesigns.splice(+b.dataset.removePants,1);savePants();paintAvatar();renderPants()})}$('#pantsForm').onsubmit=e=>{e.preventDefault();const d={id:Date.now(),name:$('#pantsName').value.trim(),main:$('#pantsMain').value,second:$('#pantsSecond').value,pattern:$('#pantsPattern').value};pantsDesigns.push(d);savePants();avatarData.pantsDesign=d;avatarData.pants=d.main;avatarData.pantsStyle='jeans';$('#pantsColor').value=d.main;paintAvatar();renderPants();e.currentTarget.reset();$('#shopNote').textContent='Custom pants created and equipped!';beep(850,.18)};
function targetGame(){const level=difficulty('target'),goal=8+(level-1)*2;stage.innerHTML=`<div class="game-ui"><p class="eyebrow">TARGET SMASH <span class="level-badge">LEVEL ${level}</span></p><h2>HIT ${goal} TARGETS</h2><p id="targetMsg">Higher levels need more hits. Win for 3 Moon Gems.</p><div class="target-field" id="targetField"></div><button class="primary" id="targetStart">START</button></div>`;let hits=0;const field=$('#targetField'),msg=$('#targetMsg');function spawn(){field.innerHTML='';const t=document.createElement('button');t.className='moving-target';const size=Math.max(30,58-level*2);t.style.width=t.style.height=size+'px';t.style.left=Math.random()*(field.clientWidth-size)+'px';t.style.top=Math.random()*(field.clientHeight-size)+'px';t.onclick=()=>{hits++;beep(420+hits*30);msg.textContent=`${hits} / ${goal} HITS`;if(hits===goal){awardMoonGems(3);return win('target')}spawn()};field.append(t)}$('#targetStart').onclick=e=>{e.currentTarget.remove();spawn()}}
function coinGame(){const level=difficulty('coins'),goal=10+(level-1)*2,total=Math.max(5,10-(level-1));stage.innerHTML=`<div class="game-ui"><p class="eyebrow">COIN RUSH <span class="level-badge">LEVEL ${level}</span></p><h2>GRAB ${goal} COINS</h2><p id="coinMsg">${total} seconds left · 0 / ${goal}</p><div class="coin-field" id="coinField"></div><button class="primary" id="coinStart">START</button></div>`;let score=0,time=total,tick;const field=$('#coinField'),msg=$('#coinMsg');function spawn(){field.innerHTML='';const c=document.createElement('button');c.className='coin';c.textContent='★';c.style.left=Math.random()*(field.clientWidth-50)+'px';c.style.top=Math.random()*(field.clientHeight-50)+'px';c.onclick=()=>{score++;beep(500+score*20);if(score>=goal){clearInterval(tick);return win('coins')}msg.textContent=`${time} seconds left · ${score} / ${goal}`;spawn()};field.append(c)}$('#coinStart').onclick=e=>{e.currentTarget.style.display='none';spawn();tick=setInterval(()=>{time--;msg.textContent=`${time} seconds left · ${score} / ${goal}`;if(time<=0){clearInterval(tick);field.innerHTML='';msg.textContent='TIME UP — TRY AGAIN';e.currentTarget.style.display='inline-block'}},1000)}}
function mathGame(){const level=difficulty('math'),goal=5+(level-1);let round=0,answer=0;stage.innerHTML=`<div class="game-ui"><p class="eyebrow">MATH MAYHEM <span class="level-badge">LEVEL ${level}</span></p><h2 id="sum">READY?</h2><p id="mathMsg">Solve ${goal} in a row.</p><div class="answers" id="answers"></div><button class="primary" id="mathStart">START</button></div>`;function next(){const limit=18+level*4,a=2+Math.floor(Math.random()*limit),b=2+Math.floor(Math.random()*limit);answer=a+b;$('#sum').textContent=`${a} + ${b} = ?`;const choices=[answer,answer+1+Math.floor(Math.random()*3),Math.max(1,answer-1-Math.floor(Math.random()*3)),answer+4+Math.floor(Math.random()*4)].sort(()=>Math.random()-.5);$('#answers').innerHTML=choices.map(n=>`<button class="answer">${n}</button>`).join('');$$('.answer').forEach(btn=>btn.onclick=()=>{if(+btn.textContent!==answer){round=0;beep(80,.2);$('#mathMsg').textContent='OOPS! STREAK RESET';return next()}round++;beep(600);if(round===goal)return win('math');$('#mathMsg').textContent=`${round} / ${goal} CORRECT`;next()})}$('#mathStart').onclick=e=>{e.currentTarget.remove();next()}}
const defaultListings=[{id:101,seller:'LunaStar',price:4,design:{id:9101,name:'Cherry Blossom',main:'#ff8fb3',second:'#fff0f6',pattern:'stripes'}},{id:102,seller:'PixelKai',price:6,design:{id:9102,name:'Cosmic Hoodie',main:'#38245f',second:'#61d8ff',pattern:'checker'}}];const marketListings=JSON.parse(localStorage.getItem('blockverse-market')||'null')||defaultListings;function saveMarket(){localStorage.setItem('blockverse-market',JSON.stringify(marketListings))}function populateListingDesigns(){const select=$('#listingDesign'),value=select.value;select.innerHTML='<option value="">Choose a design</option>'+clothingDesigns.map((d,i)=>`<option value="${i}">${safeName(d.name)}</option>`).join('');select.value=value}function renderMarket(){const me=localStorage.getItem('blockverse-username')||'Player';$('#listingCount').textContent=marketListings.length;$('#marketBalance').textContent=avatarData.moonGems;$('#marketGrid').innerHTML=marketListings.map((l,i)=>`<article class="market-card"><div class="market-swatch" style="background:${shirtPattern(l.design)}">👕</div><h4>${safeName(l.design.name)}</h4><p>by @${safeName(l.seller)}</p><button class="buy-listing" data-buy="${i}" ${l.seller===me?'disabled':''}>${l.seller===me?'YOUR LISTING':`🌙 ${l.price} · BUY`}</button>${l.seller===me?`<button class="unlist" data-unlist="${i}" title="Remove listing">×</button>`:''}</article>`).join('');$$('[data-buy]').forEach(b=>b.onclick=()=>{const l=marketListings[+b.dataset.buy];if(avatarData.moonGems<l.price){$('#marketNote').textContent='Not enough Moon Gems for that design.';beep(80,.2);return}avatarData.moonGems-=l.price;const bought={...l.design,id:Date.now(),name:l.design.name+' · '+l.seller};clothingDesigns.push(bought);saveClothes();marketListings.splice(+b.dataset.buy,1);saveMarket();paintAvatar();renderClothes();populateListingDesigns();renderMarket();$('#marketNote').textContent='Purchased! The clothing is now in My Designs.';beep(850,.2)});$$('[data-unlist]').forEach(b=>b.onclick=()=>{marketListings.splice(+b.dataset.unlist,1);saveMarket();renderMarket();$('#marketNote').textContent='Listing removed.'})}$('#listingDesign').onfocus=populateListingDesigns;$('#listingForm').onsubmit=e=>{e.preventDefault();const i=+$('#listingDesign').value,design=clothingDesigns[i],price=+$('#listingPrice').value,seller=localStorage.getItem('blockverse-username')||'Player';if(!design)return;marketListings.push({id:Date.now(),seller,price,design:{...design}});saveMarket();renderMarket();e.currentTarget.reset();$('#marketNote').textContent='Your clothing is now listed for sale!';beep(760,.15)};
