$('#friendForm').onsubmit=e=>{e.preventDefault();const name=$('#friendName').value.trim();if(friends.some(f=>f.toLowerCase()===name.toLowerCase())){$('#friendNote').textContent='That player is already your friend.';return}friends.push(name);saveFriends();renderFriends();e.currentTarget.reset();$('#friendNote').textContent=`${name} is now your friend!`;beep(700)};
function forestGame(){let night=1,fire=4,food=4,energy=4;function render(msg='Choose how to prepare for the night.'){stage.innerHTML=`<div class="game-ui"><p class="eyebrow">FOREST NIGHTS</p><h2>NIGHT ${night} / 5</h2><div class="forest-game"><div class="forest-stats"><span>🔥 ${fire}</span><span>🍎 ${food}</span><span>⚡ ${energy}</span></div><div class="forest-scene">🌲 🏕️ 🌲</div><p id="forestMsg">${msg}</p><div class="forest-actions"><button data-forest="wood">🪵 GET WOOD</button><button data-forest="food">🍓 FIND FOOD</button><button data-forest="rest">😴 REST</button></div></div></div>`;showAvatarInGame();$$('[data-forest]').forEach(b=>b.onclick=()=>turn(b.dataset.forest))}function turn(action){if(action==='wood'){fire+=3;food--;energy--}if(action==='food'){food+=3;fire--;energy--}if(action==='rest'){energy+=3;fire--;food--}let event='The camp stayed quiet.';if(Math.random()<.28){energy--;event='🐺 A wolf circled the camp!'}if(fire<=0||food<=0||energy<=0){stage.innerHTML=`<div class="game-ui"><h2>THE CAMP FELL</h2><p>Keep fire, food, and energy above zero.</p><button class="primary" onclick="forestGame()">TRY AGAIN</button></div>`;return}if(night++>=5)return bonusWin('forest');render(event)}render()}
const squishies=JSON.parse(localStorage.getItem('blockverse-squishies')||'[]');function saveSquishies(){localStorage.setItem('blockverse-squishies',JSON.stringify(squishies))}function squishyGame(){const pool=[['🐰','Bunny','common'],['🐸','Froggy','common'],['🐻','Bear','common'],['🦄','Unicorn','rare'],['🐉','Dragon','rare'],['👑','Royal Squish','legendary']];let opens=0;function render(msg='Open capsules, then trade two commons for a rare!'){stage.innerHTML=`<div class="game-ui"><p class="eyebrow">SQUISHY SWAP</p><h2>COLLECT & TRADE</h2><p id="squishMsg">${msg}</p><div class="squishy-shelf">${squishies.map(s=>`<div class="squishy-card">${s.icon}<span>${s.name}</span></div>`).join('')||'<p>No squishies yet!</p>'}</div><div class="trade-actions"><button id="openSquish">🎁 OPEN CAPSULE</button><button id="tradeSquish">🔄 TRADE 2 COMMON</button><button id="finishSquish">✓ FINISH COLLECTION</button></div></div>`;$('#openSquish').onclick=()=>{if(opens>=6){render('You opened every capsule this round. Try trading!');return}opens++;const roll=Math.random(),choices=roll>.93?pool.slice(5):roll>.72?pool.slice(3,5):pool.slice(0,3),p=choices[Math.floor(Math.random()*choices.length)];squishies.push({id:Date.now()+Math.random(),icon:p[0],name:p[1],rarity:p[2]});saveSquishies();render(`You found ${p[0]} ${p[1]}!`)};$('#tradeSquish').onclick=()=>{const commons=squishies.map((s,i)=>[s,i]).filter(x=>x[0].rarity==='common');if(commons.length<2){render('You need two common squishies to trade.');return}const ids=[commons[0][1],commons[1][1]].sort((a,b)=>b-a);ids.forEach(i=>squishies.splice(i,1));const p=pool[3+Math.floor(Math.random()*2)];squishies.push({id:Date.now(),icon:p[0],name:p[1],rarity:'rare'});saveSquishies();render(`Trade complete — you got ${p[0]} ${p[1]}!`)};$('#finishSquish').onclick=()=>{if(squishies.length>=5||squishies.some(s=>s.rarity==='legendary'))bonusWin('squishy');else render('Collect at least five squishies or one legendary!')}}render()}
function renderUpgrades(){$('#upgradeBalance').textContent=avatarData.moonGems;$$('[data-upgrade]').forEach(card=>{const name=card.dataset.upgrade,level=upgradeLevel(name),max=+card.dataset.max,cost=+card.dataset.base*(level+1),button=card.querySelector('button');card.querySelector('.upgrade-level').textContent=`LEVEL ${level} / ${max}`;card.classList.toggle('maxed',level>=max);button.disabled=level>=max;button.textContent=level>=max?'✓ MAX LEVEL':`UPGRADE · 🌙 ${cost}`;button.onclick=()=>{if(avatarData.moonGems<cost){$('#upgradeNote').textContent='Not enough Moon Gems. Win games to earn more!';beep(80,.2);return}avatarData.moonGems-=cost;gameUpgrades[name]=level+1;saveUpgrades();paintAvatar();renderUpgrades();renderBackpack();$('#upgradeNote').textContent=`${card.querySelector('h3').textContent} upgraded to level ${level+1}!`;beep(820,.18)}})}
function survivalGame(){const level=difficulty('survival'),maxHp=5+upgradeLevel('hearts'),duration=12+level;stage.innerHTML=`<div class="game-ui"><p class="eyebrow">NIGHT ESCAPE <span class="level-badge">LEVEL ${level}</span></p><h2>SURVIVE ${duration} SECONDS</h2><div class="survival-hud"><span id="survivalHp">${'❤️'.repeat(maxHp)}</span><span id="survivalTime">${duration}s</span></div><div class="survival-board" id="survivalBoard"><div class="survivor" id="survivor"></div></div><p>Move with W A S D or arrow keys. Enemies are slower now.</p></div>`;const board=$('#survivalBoard'),hero=$('#survivor');let x=board.clientWidth/2,y=board.clientHeight/2,hp=maxHp,enemies=[],running=true,lastSpawn=0,start=performance.now(),lastHit=0;function draw(){hero.style.left=x+'px';hero.style.top=y+'px'}function key(e){const speed=17+upgradeLevel('speed')*3,map={w:[0,-speed],s:[0,speed],a:[-speed,0],d:[speed,0],ArrowUp:[0,-speed],ArrowDown:[0,speed],ArrowLeft:[-speed,0],ArrowRight:[speed,0]};if(map[e.key]){e.preventDefault();x=Math.max(0,Math.min(board.clientWidth-30,x+map[e.key][0]));y=Math.max(0,Math.min(board.clientHeight-30,y+map[e.key][1]));draw()}}function spawn(){const el=document.createElement('i');el.className='shadow-enemy';const side=Math.floor(Math.random()*4),p={el,x:side===0?0:side===1?board.clientWidth-26:Math.random()*board.clientWidth,y:side===2?0:side===3?board.clientHeight-26:Math.random()*board.clientHeight};board.append(el);enemies.push(p)}function loop(t){if(!running)return;const left=Math.max(0,duration-(t-start)/1000);$('#survivalTime').textContent=Math.ceil(left)+'s';if(left<=0){running=false;document.removeEventListener('keydown',key);gameCleanup=null;return bonusWin('survival')}if(t-lastSpawn>Math.max(750,1650-level*55)){spawn();lastSpawn=t}for(const e of enemies){const dx=x-e.x,dy=y-e.y,d=Math.hypot(dx,dy)||1,speed=.65+level*.07;e.x+=dx/d*speed;e.y+=dy/d*speed;e.el.style.left=e.x+'px';e.el.style.top=e.y+'px';if(Math.abs(e.x-x)<24&&Math.abs(e.y-y)<24&&t-lastHit>1200){hp--;lastHit=t;$('#survivalHp').textContent='❤️'.repeat(hp)+'🖤'.repeat(maxHp-hp);beep(80,.2);if(hp<=0){running=false;document.removeEventListener('keydown',key);gameCleanup=null;stage.innerHTML=`<div class="game-ui"><h2>ALMOST!</h2><p>The shadows caught you. Keep moving and try again.</p><button class="primary" onclick="survivalGame();showAvatarInGame()">RETRY</button></div>`;return}}}requestAnimationFrame(loop)}document.addEventListener('keydown',key);gameCleanup=()=>{running=false;document.removeEventListener('keydown',key)};draw();requestAnimationFrame(loop)}
function targetGame(){const level=difficulty('target'),goal=8+(level-1)*2,lens=upgradeLevel('target');stage.innerHTML=`<div class="game-ui"><p class="eyebrow">TARGET SMASH <span class="level-badge">LEVEL ${level}</span></p><h2>HIT ${goal} TARGETS</h2><p id="targetMsg">Target Lens level ${lens} is active.</p><div class="target-field" id="targetField"></div><button class="primary" id="targetStart">START</button></div>`;let hits=0;const field=$('#targetField'),msg=$('#targetMsg');function spawn(){field.innerHTML='';const t=document.createElement('button');t.className='moving-target';const size=Math.max(32,58-level*2+lens*9);t.style.width=t.style.height=size+'px';t.style.left=Math.random()*(field.clientWidth-size)+'px';t.style.top=Math.random()*(field.clientHeight-size)+'px';t.onclick=()=>{hits++;beep(420+hits*30);msg.textContent=`${hits} / ${goal} HITS`;if(hits===goal){awardMoonGems(3);return win('target')}spawn()};field.append(t)}$('#targetStart').onclick=e=>{e.currentTarget.remove();spawn()}}
function coinGame(){const level=difficulty('coins'),goal=10+(level-1)*2,total=Math.max(5,10-(level-1))+upgradeLevel('clock')*2;stage.innerHTML=`<div class="game-ui"><p class="eyebrow">COIN RUSH <span class="level-badge">LEVEL ${level}</span></p><h2>GRAB ${goal} COINS</h2><p id="coinMsg">${total} seconds left · 0 / ${goal}</p><div class="coin-field" id="coinField"></div><button class="primary" id="coinStart">START</button></div>`;let score=0,time=total,tick;const field=$('#coinField'),msg=$('#coinMsg');function spawn(){field.innerHTML='';const c=document.createElement('button');c.className='coin';c.textContent='★';c.style.left=Math.random()*(field.clientWidth-50)+'px';c.style.top=Math.random()*(field.clientHeight-50)+'px';c.onclick=()=>{score++;beep(500+score*20);if(score>=goal){clearInterval(tick);return win('coins')}msg.textContent=`${time} seconds left · ${score} / ${goal}`;spawn()};field.append(c)}$('#coinStart').onclick=e=>{e.currentTarget.style.display='none';spawn();tick=setInterval(()=>{time--;msg.textContent=`${time} seconds left · ${score} / ${goal}`;if(time<=0){clearInterval(tick);field.innerHTML='';msg.textContent='TIME UP — TRY AGAIN';e.currentTarget.style.display='inline-block'}},1000)}}
function memoryGame(){let seq=[],input=[],roundLevel=1,busy=false,target=5+difficulty('memory')-1,hold=380+upgradeLevel('memory')*180;stage.innerHTML=`<div class="game-ui"><p class="eyebrow">COLOR CRAZE <span class="level-badge">LEVEL ${difficulty('memory')}</span></p><h2>REPEAT THE PATTERN</h2><p id="memoryMsg">Reach sequence ${target}. Focus upgrade adds viewing time.</p><div class="pads">${[0,1,2,3].map(i=>`<button class="pad" data-pad="${i}"></button>`).join('')}</div><button class="primary" id="memoryStart">START</button></div>`;const pads=$$('.pad');async function flash(i){pads[i].classList.add('lit');beep(260+i*130);await new Promise(r=>setTimeout(r,hold));pads[i].classList.remove('lit');await new Promise(r=>setTimeout(r,100))}async function round(){busy=true;input=[];seq.push(Math.floor(Math.random()*4));$('#memoryMsg').textContent=`SEQUENCE ${roundLevel} — WATCH`;await new Promise(r=>setTimeout(r,400));for(const i of seq)await flash(i);busy=false;$('#memoryMsg').textContent='YOUR TURN'}pads.forEach((p,i)=>p.onclick=async()=>{if(busy||!seq.length)return;await flash(i);input.push(i);const n=input.length-1;if(input[n]!==seq[n]){seq=[];roundLevel=1;$('#memoryMsg').textContent='TRY AGAIN';beep(90,.2);return}if(input.length===seq.length){roundLevel++;if(roundLevel>target)return win('memory');busy=true;setTimeout(round,500)}});$('#memoryStart').onclick=()=>{if(!busy){seq=[];roundLevel=1;round()}}}
const backpackDesigns=JSON.parse(localStorage.getItem('blockverse-backpacks')||'[]');function saveBackpacks(){localStorage.setItem('blockverse-backpacks',JSON.stringify(backpackDesigns))}function paintBackpack(){const bag=avatarData.backpack||{style:'classic',main:'#e75569',second:'#8b2740'};document.documentElement.style.setProperty('--bag-main',bag.main);document.documentElement.style.setProperty('--bag-second',bag.second);document.documentElement.style.setProperty('--bag-icon',bag.style==='heart'?'"♥"':bag.style==='star'?'"★"':'""');$$('.player-avatar').forEach(a=>{if(!a.querySelector('.backpack-item')){const el=document.createElement('i');el.className='backpack-item';a.prepend(el)}});localStorage.setItem('blockverse-avatar',JSON.stringify(avatarData))}function bagCapacity(){return 12+upgradeLevel('bagspace')*6}function allInventory(){return[...clothingDesigns.map(x=>({icon:'👕',name:x.name})),...pantsDesigns.map(x=>({icon:'👖',name:x.name})),...backpackDesigns.map(x=>({icon:'🎒',name:x.name})),...squishies.map(x=>({icon:x.icon,name:x.name})),...avatarData.owned.filter(x=>x!=='classic').map(x=>({icon:x==='crown'?'♛':'🧢',name:x}))]}function hasBagSpace(){return allInventory().length<bagCapacity()}function renderBackpack(){const items=allInventory(),cap=bagCapacity();$('#bagCubes').textContent=state.done.size;$('#bagGems').textContent=avatarData.moonGems;$('#bagCapacityText').textContent=`${items.length} / ${cap}`;$('#bagCapacityFill').style.width=Math.min(100,items.length/cap*100)+'%';$('#inventoryGrid').innerHTML=items.map(x=>`<div class="inventory-item"><b>${x.icon}</b><span>${safeName(x.name)}</span></div>`).join('')+Array.from({length:Math.max(0,cap-items.length)},()=>'<div class="inventory-item inventory-empty">EMPTY</div>').join('')}let chosenBag='classic';$$('[data-bag]').forEach(b=>b.onclick=()=>{$$('[data-bag]').forEach(x=>x.classList.remove('active'));b.classList.add('active');chosenBag=b.dataset.bag;avatarData.backpack={style:chosenBag,main:chosenBag==='heart'?'#ff6fa5':chosenBag==='star'?'#6653ce':'#e75569',second:'#8b2740',name:chosenBag};paintBackpack();beep(640)});$('#backpackForm').onsubmit=e=>{e.preventDefault();if(!hasBagSpace()){$('#shopNote').textContent='Backpack full — buy more space in the Upgrade Lab.';return}if(avatarData.moonGems<4){$('#shopNote').textContent='You need 4 Moon Gems to design a backpack.';beep(80,.2);return}avatarData.moonGems-=4;const bag={id:Date.now(),style:chosenBag,main:$('#bagMain').value,second:$('#bagSecond').value,name:$('#backpackName').value.trim()};backpackDesigns.push(bag);avatarData.backpack=bag;saveBackpacks();paintAvatar();paintBackpack();renderBackpacks();renderBackpack();e.currentTarget.reset();$('#shopNote').textContent='Custom backpack created and equipped!';beep(850,.2)};function renderBackpacks(){$('#myBackpacks').innerHTML=backpackDesigns.map((b,i)=>`<article class="design-card"><div class="design-swatch" style="background:linear-gradient(135deg,${b.main},${b.second})">🎒</div><h4>${safeName(b.name)}</h4><div class="design-actions"><button data-wear-bag="${i}">EQUIP</button></div></article>`).join('');$$('[data-wear-bag]').forEach(b=>b.onclick=()=>{avatarData.backpack=backpackDesigns[+b.dataset.wearBag];paintBackpack();beep(700)})}
const creationCosts={creatorForm:2,clothesForm:3,pantsForm:3};document.addEventListener('submit',e=>{const cost=creationCosts[e.target.id];if(!cost)return;if((e.target.id==='clothesForm'||e.target.id==='pantsForm')&&!hasBagSpace()){e.preventDefault();e.stopImmediatePropagation();$('#shopNote').textContent='Backpack full — upgrade its space first.';return}if(avatarData.moonGems<cost){e.preventDefault();e.stopImmediatePropagation();const note=e.target.id==='creatorForm'?$('#creatorNote'):$('#shopNote');note.textContent=`You need ${cost} Moon Gems to create this.`;beep(80,.2);return}avatarData.moonGems-=cost;paintAvatar();setTimeout(renderBackpack)},true);$('#saveBeauty').addEventListener('click',e=>{if(avatarData.moonGems<1){e.preventDefault();e.stopImmediatePropagation();$('#shopNote').textContent='Hair & Face Studio costs 1 Moon Gem.';beep(80,.2);return}avatarData.moonGems-=1;paintAvatar();setTimeout(renderBackpack)},true);
function forestGame(){let night=1,hp=10,fire=6,food=6,coins=0,weapon={name:'Stick',damage:1},enemyHp=3;const weapons=[{name:'Stone Axe',damage:2,cost:5,icon:'🪓'},{name:'Moon Sword',damage:4,cost:14,icon:'⚔️'},{name:'Star Bow',damage:7,cost:30,icon:'🏹'}];function render(msg='The forest never ends. Prepare or attack!'){stage.innerHTML=`<div class="game-ui"><p class="eyebrow">ENDLESS FOREST NIGHTS</p><h2>NIGHT ${night}</h2><div class="forest-combat"><div class="forest-stats"><span>❤️ ${hp}/10</span><span>🔥 ${fire}</span><span>🍎 ${food}</span><span>🪙 ${coins}</span><span>${weapon.name}</span></div><div class="forest-world"><span>🏕️</span><span class="forest-enemy">${night%5===0?'🐻':'🐺'} ${enemyHp}HP</span></div><p class="combat-log">${msg}</p><div class="forest-actions"><button data-action="attack">⚔️ ATTACK</button><button data-action="food">🍓 FORAGE</button><button data-action="fire">🪵 TEND FIRE</button></div><p>WEAPON STORE</p><div class="weapon-store">${weapons.map((w,i)=>`<button data-weapon="${i}" ${weapon.damage>=w.damage?'disabled':''}>${w.icon} ${w.name}<br>🪙 ${w.cost}</button>`).join('')}</div></div></div>`;showAvatarInGame();$$('[data-action]').forEach(b=>b.onclick=()=>act(b.dataset.action));$$('[data-weapon]').forEach(b=>b.onclick=()=>buyWeapon(weapons[+b.dataset.weapon]))}function buyWeapon(w){if(coins<w.cost){render('Defeat more creatures to earn forest coins.');return}coins-=w.cost;weapon={name:w.name,damage:w.damage};render(`${w.icon} ${w.name} equipped!`)}function act(type){let msg='';if(type==='attack'){enemyHp-=weapon.damage;msg=`You strike for ${weapon.damage} damage!`}if(type==='food'){food+=3;msg='You gathered wild berries.'}if(type==='fire'){fire+=3;msg='The campfire burns brighter.'}if(enemyHp>0){hp-=Math.max(1,Math.floor(night/8)+1);msg+=' The creature attacks back!'}else{coins+=2+Math.floor(night/3);night++;fire--;food--;enemyHp=3+Math.floor(night/2)+(night%5===0?4:0);hp=Math.min(10,hp+1);msg=`Creature defeated! Night ${night} begins.`;if(night%5===1){avatarData.moonGems+=2;paintAvatar();msg+=' Milestone: +2 Moon Gems!'}}if(fire<=0||food<=0)hp-=2;if(hp<=0){stage.innerHTML=`<div class="game-ui"><h2>YOU SURVIVED ${night} NIGHTS</h2><p>The endless forest finally claimed your camp.</p><button class="primary" onclick="forestGame()">NEW RUN</button></div>`;return}render(msg)}render()}
function squishyGame(){const pool={basic:[['🐰','Bunny','common'],['🐸','Froggy','common'],['🐻','Bear','common']],sparkle:[['🦄','Unicorn','rare'],['🐉','Dragon','rare'],['🦋','Butterfly','rare']],royal:[['👑','Royal Squish','legendary'],['🌙','Moon Kitty','legendary'],['🌈','Rainbow Pup','legendary']]};function render(msg='Buy a capsule to discover a squishy!'){stage.innerHTML=`<div class="game-ui"><p class="eyebrow">SQUISHY CAPSULE STORE</p><h2>COLLECT & TRADE</h2><p class="capsule-balance">🌙 ${avatarData.moonGems} MOON GEMS</p><p>${msg}</p><div class="capsule-shop"><button class="capsule" data-capsule="basic" data-cost="1"><b>🔵</b>BASIC · 🌙 1</button><button class="capsule" data-capsule="sparkle" data-cost="3"><b>🟣</b>SPARKLE · 🌙 3</button><button class="capsule" data-capsule="royal" data-cost="5"><b>🟡</b>ROYAL · 🌙 5</button></div><div class="squishy-shelf">${squishies.map(s=>`<div class="squishy-card">${s.icon}<span>${s.name}<br>${s.rarity}</span></div>`).join('')||'<p>Your shelf is empty.</p>'}</div><div class="trade-actions"><button id="tradeSquish">🔄 TRADE 2 COMMON</button><button id="finishSquish">✓ FINISH COLLECTION</button></div></div>`;$$('[data-capsule]').forEach(b=>b.onclick=()=>buy(b.dataset.capsule,+b.dataset.cost));$('#tradeSquish').onclick=trade;$('#finishSquish').onclick=()=>{if(squishies.length>=5||squishies.some(s=>s.rarity==='legendary'))bonusWin('squishy');else render('Collect five squishies or one legendary to finish!')}}function buy(type,cost){if(!hasBagSpace()){render('Your backpack is full. Upgrade its space first.');return}if(avatarData.moonGems<cost){render(`You need ${cost} Moon Gems for that capsule.`);beep(80,.2);return}avatarData.moonGems-=cost;const choices=pool[type],p=choices[Math.floor(Math.random()*choices.length)];squishies.push({id:Date.now()+Math.random(),icon:p[0],name:p[1],rarity:p[2]});saveSquishies();paintAvatar();renderBackpack();render(`Capsule opened — ${p[0]} ${p[1]}!`);beep(820,.18)}function trade(){const commons=squishies.map((s,i)=>[s,i]).filter(x=>x[0].rarity==='common');if(commons.length<2){render('You need two common squishies to trade.');return}[commons[1][1],commons[0][1]].forEach(i=>squishies.splice(i,1));const p=pool.sparkle[Math.floor(Math.random()*pool.sparkle.length)];squishies.push({id:Date.now(),icon:p[0],name:p[1],rarity:'rare'});saveSquishies();renderBackpack();render(`Trade complete — ${p[0]} ${p[1]}!`)}render()}
function soloObbyGame(){stage.innerHTML=`<div class="game-ui"><p class="eyebrow">SOLO OBBY</p><h2>SKY CLIMB</h2><p id="soloMsg">Use W A S D or arrow keys. Red spikes reset you.</p><div class="solo-obby-board" id="soloBoard"><div class="obby-goal">🏁 FINISH</div><i class="obby-wall" style="left:0;top:245px;width:350px;height:18px"></i><i class="obby-wall" style="right:0;top:165px;width:350px;height:18px"></i><i class="obby-wall" style="left:0;top:85px;width:350px;height:18px"></i><i class="obby-hazard" style="left:180px;top:292px;width:100px;height:30px"></i><div class="solo-runner" id="soloRunner"></div></div></div>`;const board=$('#soloBoard'),runner=$('#soloRunner'),start={x:20,y:290};let x=start.x,y=start.y;const walls=[{x:0,y:245,w:350,h:18},{x:150,y:165,w:350,h:18},{x:0,y:85,w:350,h:18}],hazard={x:180,y:285,w:100,h:40};function draw(){runner.style.left=x+'px';runner.style.top=y+'px'}function blocked(nx,ny){return nx<0||ny<0||nx>board.clientWidth-26||ny>board.clientHeight-30||walls.some(w=>nx+26>w.x&&nx<w.x+w.w&&ny+30>w.y&&ny<w.y+w.h)}function key(e){const m={w:[0,-13],s:[0,13],a:[-13,0],d:[13,0],ArrowUp:[0,-13],ArrowDown:[0,13],ArrowLeft:[-13,0],ArrowRight:[13,0]}[e.key];if(!m)return;e.preventDefault();const nx=x+m[0],ny=y+m[1];if(!blocked(nx,ny)){x=nx;y=ny}if(x+26>hazard.x&&x<hazard.x+hazard.w&&y+30>hazard.y){x=start.x;y=start.y;$('#soloMsg').textContent='Spikes! Back to the start.'}if(x>board.clientWidth-90&&y<55){document.removeEventListener('keydown',key);gameCleanup=null;return bonusWin('soloobby')}draw()}document.addEventListener('keydown',key);gameCleanup=()=>document.removeEventListener('keydown',key);draw()}
function builderGame(){let blocks=JSON.parse(localStorage.getItem('blockverse-build')||'[]'),color='#ff6f61';function render(msg='Place at least 15 blocks to complete a build.'){stage.innerHTML=`<div class="game-ui"><p class="eyebrow">BUILDING SANDBOX</p><h2>BLOCK BUILDER</h2><p id="buildMsg">${msg}</p><div class="block-palette">${['#ff6f61','#ffd429','#23c768','#35a9ff','#9b6cff'].map((c,i)=>`<button data-color="${c}" style="--color:${c}" class="${i===0?'active':''}"></button>`).join('')}</div><div class="build-board">${Array.from({length:70},(_,i)=>`<button class="build-cell ${blocks[i]?'filled':''}" data-cell="${i}" style="--block:${blocks[i]||'transparent'}"></button>`).join('')}</div><div class="build-actions"><button id="saveBuild">SAVE BLUEPRINT</button><button id="clearBuild">CLEAR</button><button id="finishBuild">FINISH BUILD</button></div></div>`;$$('[data-color]').forEach(b=>b.onclick=()=>{color=b.dataset.color;$$('[data-color]').forEach(x=>x.classList.toggle('active',x===b))});$$('[data-cell]').forEach(b=>b.onclick=()=>{const i=+b.dataset.cell;blocks[i]=blocks[i]?null:color;b.classList.toggle('filled',!!blocks[i]);b.style.setProperty('--block',blocks[i]||'transparent')});$('#saveBuild').onclick=()=>{localStorage.setItem('blockverse-build',JSON.stringify(blocks));$('#buildMsg').textContent='Blueprint saved! It will be here next time.';beep(700)};$('#clearBuild').onclick=()=>{blocks=[];localStorage.removeItem('blockverse-build');render('Build cleared. Start something new!')};$('#finishBuild').onclick=()=>{if(blocks.filter(Boolean).length>=15){localStorage.setItem('blockverse-build',JSON.stringify(blocks));bonusWin('builder')}else $('#buildMsg').textContent=`Place ${15-blocks.filter(Boolean).length} more blocks.`}}render()}
const sweaterDesigns=JSON.parse(localStorage.getItem('blockverse-sweaters')||'[]');function saveSweaters(){localStorage.setItem('blockverse-sweaters',JSON.stringify(sweaterDesigns))}function renderSweaters(){$('#mySweaters').innerHTML=sweaterDesigns.map((d,i)=>`<article class="design-card"><div class="design-swatch" style="background:${shirtPattern(d)}">🧶</div><h4>${safeName(d.name)}</h4><div class="design-actions"><button data-wear-sweater="${i}">EQUIP</button></div></article>`).join('');$$('[data-wear-sweater]').forEach(b=>b.onclick=()=>{const d=sweaterDesigns[+b.dataset.wearSweater];avatarData.design=d;avatarData.outfit='sweater';avatarData.shirt=d.main;paintAvatar();paintOutfit();beep(720)})}$('#sweaterForm').onsubmit=e=>{e.preventDefault();if(!hasBagSpace()){$('#shopNote').textContent='Backpack full — buy more space first.';return}if(avatarData.moonGems<3){$('#shopNote').textContent='You need 3 Moon Gems to make a sweater.';beep(80,.2);return}avatarData.moonGems-=3;const d={id:Date.now(),name:$('#sweaterName').value.trim(),main:$('#sweaterMain').value,second:$('#sweaterSecond').value,pattern:$('#sweaterPattern').value,kind:'sweater'};sweaterDesigns.push(d);clothingDesigns.push(d);saveSweaters();saveClothes();avatarData.design=d;avatarData.outfit='sweater';avatarData.shirt=d.main;paintAvatar();paintOutfit();renderSweaters();renderClothes();renderBackpack();e.currentTarget.reset();beep(850,.2)};
function inventoryEntries(){const e=[{type:'classicbag',index:-1,icon:'🎒',name:'Classic Backpack',value:0,equipped:!avatarData.backpack?.id}];clothingDesigns.forEach((x,i)=>e.push({type:'clothes',index:i,id:x.id,icon:x.kind==='sweater'?'🧶':'👕',name:x.name,value:2,equipped:avatarData.design?.id===x.id}));pantsDesigns.forEach((x,i)=>e.push({type:'pants',index:i,id:x.id,icon:'👖',name:x.name,value:2,equipped:avatarData.pantsDesign?.id===x.id}));backpackDesigns.forEach((x,i)=>e.push({type:'bags',index:i,id:x.id,icon:'🎒',name:x.name,value:2,equipped:avatarData.backpack?.id===x.id}));squishies.forEach((x,i)=>e.push({type:'squishy',index:i,id:x.id,icon:x.icon,name:x.name,value:x.rarity==='legendary'?8:x.rarity==='rare'?3:1,equipped:false}));avatarData.owned.forEach((x,i)=>{if(x!=='classic')e.push({type:'owned',index:i,icon:x==='crown'?'♛':'🧢',name:x,value:2,equipped:avatarData.accessory===x||avatarData.outfit===x})});return e}function allInventory(){return inventoryEntries().filter(x=>x.type!=='classicbag')}function renderBackpack(){const entries=inventoryEntries(),used=entries.length-1,cap=bagCapacity();$('#bagCubes').textContent=state.done.size;$('#bagGems').textContent=avatarData.moonGems;$('#bagCapacityText').textContent=`${used} / ${cap}`;$('#bagCapacityFill').style.width=Math.min(100,used/cap*100)+'%';$('#inventoryGrid').innerHTML='<div class="bag-help">PUT ON equips a backpack. Sell items for Moon Gems, or discard them permanently.</div>'+entries.map((x,i)=>`<div class="inventory-item ${x.equipped?'equipped':''}"><b>${x.icon}</b><span>${safeName(x.name)}</span>${x.equipped?'<em>✓ EQUIPPED</em>':''}${x.value?`<small class="inventory-value">VALUE 🌙 ${x.value}</small>`:''}<div class="inventory-actions">${x.type==='bags'||x.type==='classicbag'?`<button class="put-on" data-put-bag="${i}">PUT ON</button>`:''}${x.value?`<button class="sell-item" data-sell="${i}">SELL</button><button class="discard-item" data-discard="${i}">DISCARD</button>`:''}</div></div>`).join('')+Array.from({length:Math.max(0,cap-used)},()=>'<div class="inventory-item inventory-empty">EMPTY</div>').join('');$$('[data-put-bag]').forEach(b=>b.onclick=()=>{const item=inventoryEntries()[+b.dataset.putBag];avatarData.backpack=item.type==='classicbag'?{style:'classic',main:'#e75569',second:'#8b2740',name:'Classic Pack'}:backpackDesigns[item.index];paintBackpack();renderBackpack();beep(720)});$$('[data-sell]').forEach(b=>b.onclick=()=>removeInventory(inventoryEntries()[+b.dataset.sell],true));$$('[data-discard]').forEach(b=>b.onclick=()=>{const item=inventoryEntries()[+b.dataset.discard];if(confirm(`Discard ${item.name}? This cannot be undone.`))removeInventory(item,false)})}function removeInventory(item,selling){if(item.type==='clothes'){const removed=clothingDesigns.splice(item.index,1)[0];if(avatarData.design?.id===removed.id){avatarData.design=null;avatarData.outfit='classic'}const si=sweaterDesigns.findIndex(x=>x.id===removed.id);if(si>=0){sweaterDesigns.splice(si,1);saveSweaters()}saveClothes()}if(item.type==='pants'){const removed=pantsDesigns.splice(item.index,1)[0];if(avatarData.pantsDesign?.id===removed.id)avatarData.pantsDesign=null;savePants()}if(item.type==='bags'){const removed=backpackDesigns.splice(item.index,1)[0];if(avatarData.backpack?.id===removed.id)avatarData.backpack={style:'classic',main:'#e75569',second:'#8b2740',name:'Classic Pack'};saveBackpacks()}if(item.type==='squishy'){squishies.splice(item.index,1);saveSquishies()}if(item.type==='owned'){const name=avatarData.owned[item.index];avatarData.owned.splice(item.index,1);if(avatarData.accessory===name)avatarData.accessory='none';if(avatarData.outfit===name)avatarData.outfit='classic'}if(selling)avatarData.moonGems+=item.value;paintAvatar();paintOutfit();paintBackpack();renderClothes();renderPants();renderBackpacks();renderSweaters();renderShop();renderBackpack();beep(selling?760:120,.15)}
function soloObbyGame(){const platforms=[{x:0,y:300,w:80},{x:105,y:255,w:85},{x:220,y:210,w:85},{x:105,y:160,w:90},{x:245,y:112,w:90},{x:380,y:62,w:105}];stage.innerHTML=`<div class="game-ui"><p class="eyebrow">3D PLATFORM OBBY</p><h2>SKY CLIMB</h2><p id="soloMsg">Move with A/D or arrows. Jump with W, ↑, or Space.</p><div class="solo-obby-board" id="soloBoard"><div class="obby-goal">🏁 FINISH</div><div class="obby-lava"></div>${platforms.map((p,i)=>`<i class="jump-platform" style="left:${p.x}px;top:${p.y}px;width:${p.w}px"></i>${i===3?`<b class="checkpoint" style="left:${p.x+30}px;top:${p.y-30}px">🚩</b>`:''}`).join('')}<div class="jump-player" id="jumpPlayer"></div></div></div>`;const board=$('#soloBoard'),player=$('#jumpPlayer');let x=20,y=260,vx=0,vy=0,grounded=false,running=true,spawn={x:20,y:260},left=false,right=false;function down(e){if(['ArrowLeft','a'].includes(e.key))left=true;if(['ArrowRight','d'].includes(e.key))right=true;if(['ArrowUp','w',' '].includes(e.key)&&grounded){vy=-10.5;grounded=false;beep(380)}}function up(e){if(['ArrowLeft','a'].includes(e.key))left=false;if(['ArrowRight','d'].includes(e.key))right=false}function loop(){if(!running)return;vx=(right?3.3:0)-(left?3.3:0);x=Math.max(0,Math.min(board.clientWidth-25,x+vx));const oldY=y;vy+=.52;y+=vy;grounded=false;if(vy>=0)for(const p of platforms){if(x+25>p.x&&x<p.x+p.w&&oldY+34<=p.y+5&&y+34>=p.y){y=p.y-34;vy=0;grounded=true;if(p.y===160){spawn={x:p.x+25,y:p.y-34};$('#soloMsg').textContent='Checkpoint reached! 🚩'}}}if(y>310){x=spawn.x;y=spawn.y;vy=0;$('#soloMsg').textContent='Lava! Returned to checkpoint.';beep(70,.2)}if(x>390&&y<45){running=false;document.removeEventListener('keydown',down);document.removeEventListener('keyup',up);gameCleanup=null;return bonusWin('soloobby')}player.style.left=x+'px';player.style.top=y+'px';requestAnimationFrame(loop)}document.addEventListener('keydown',down);document.addEventListener('keyup',up);gameCleanup=()=>{running=false;document.removeEventListener('keydown',down);document.removeEventListener('keyup',up)};requestAnimationFrame(loop)}
function forestGame(){let night=1,hp=10,fire=6,food=6,coins=0,weapon={name:'Stick',damage:1},enemyHp=3,heartHere=true;const weapons=[{name:'Stone Axe',damage:2,cost:5,icon:'🪓'},{name:'Moon Sword',damage:4,cost:14,icon:'⚔️'},{name:'Star Bow',damage:7,cost:30,icon:'🏹'}];function render(msg='A heart may be hidden nearby. Search, prepare, or attack!'){stage.innerHTML=`<div class="game-ui"><p class="eyebrow">ENDLESS FOREST NIGHTS</p><h2>NIGHT ${night}</h2><div class="forest-combat"><div class="forest-stats"><span>❤️ ${hp}/10</span><span>🔥 ${fire}</span><span>🍎 ${food}</span><span>🪙 ${coins}</span><span>${weapon.name}</span></div><div class="forest-world"><span>🏕️</span><span>${heartHere?'💗':'🌲'}</span><span class="forest-enemy">${night%5===0?'🐻':'🐺'} ${enemyHp}HP</span></div><p class="combat-log">${msg}</p><div class="forest-actions" style="grid-template-columns:repeat(4,1fr)"><button data-action="attack">⚔️ ATTACK</button><button data-action="search">💗 FIND HEART</button><button data-action="food">🍓 FORAGE</button><button data-action="fire">🪵 FIRE</button></div><p>WEAPON STORE</p><div class="weapon-store">${weapons.map((w,i)=>`<button data-weapon="${i}" ${weapon.damage>=w.damage?'disabled':''}>${w.icon} ${w.name}<br>🪙 ${w.cost}</button>`).join('')}</div></div></div>`;showAvatarInGame();$$('[data-action]').forEach(b=>b.onclick=()=>act(b.dataset.action));$$('[data-weapon]').forEach(b=>b.onclick=()=>buy(weapons[+b.dataset.weapon]))}function buy(w){if(coins<w.cost){render('Defeat more creatures for forest coins.');return}coins-=w.cost;weapon={name:w.name,damage:w.damage};render(`${w.icon} ${w.name} equipped!`)}function act(type){let msg='';if(type==='attack'){enemyHp-=weapon.damage;msg=`You deal ${weapon.damage} damage!`}if(type==='food'){food+=3;msg='You gathered berries.'}if(type==='fire'){fire+=3;msg='The fire grows brighter.'}if(type==='search'){if(heartHere){hp=Math.min(10,hp+3);heartHere=false;msg='💗 Hidden heart found! Restored 3 health.';beep(850,.2)}else msg='No heart here tonight. Keep searching later.'}if(enemyHp>0){hp-=Math.max(1,Math.floor(night/9)+1);msg+=' The creature strikes back.'}else{coins+=2+Math.floor(night/3);night++;fire--;food--;enemyHp=3+Math.floor(night/2)+(night%5===0?4:0);heartHere=Math.random()<.55;hp=Math.min(10,hp+1);msg=`Enemy defeated. Night ${night} begins.${heartHere?' You hear a magical heartbeat nearby!':''}`;if(night%5===1){avatarData.moonGems+=2;paintAvatar();msg+=' +2 Moon Gems!'}}if(fire<=0||food<=0)hp-=2;if(hp<=0){stage.innerHTML=`<div class="game-ui"><h2>${night} NIGHTS SURVIVED</h2><p>Search for more hearts on your next run.</p><button class="primary" onclick="forestGame()">NEW RUN</button></div>`;return}render(msg)}render()}
const quickGames={moondash:{title:'MOON DASH',icon:'🌙',decoys:['⭐','☄️','🪐'],goal:12,time:18,mode:'chase'},petrescue:{title:'PET RESCUE',icon:'🐶',icons:['🐶','🐱','🐰','🐹'],goal:8,time:25,mode:'choose'},pizzapop:{title:'PIZZA PANIC',icon:'🍕',decoys:['🍅','🧀','🥦'],goal:14,time:20,mode:'chase'},bubblepop:{title:'BUBBLE BURST',icon:'🫧',decoys:['💣','⚫','🕷️'],goal:15,time:18,mode:'chase'},gemhunt:{title:'GEM HUNT',icon:'💎',icons:['💎','🔷','🔮','🪨'],goal:9,time:24,mode:'choose'},fashionrun:{title:'FASHION RUN',icon:'👗',icons:['👗','👠','👜','👒'],goal:10,time:25,mode:'choose'},fishing:{title:'STAR FISHING',icon:'🐟',decoys:['🦈','🪼','🗑️'],goal:12,time:20,mode:'chase'},snowball:{title:'SNOWBALL BLAST',icon:'⛄',decoys:['🌲','🧊','🎁'],goal:13,time:18,mode:'chase'},cakestack:{title:'CAKE STACK',icon:'🍰',icons:['🍰','🧁','🎂','🍩'],goal:10,time:25,mode:'choose'},spaceminer:{title:'SPACE MINER',icon:'☄️',decoys:['🛸','👾','🕳️'],goal:14,time:20,mode:'chase'}};
function quickArcadeGame(game){const cfg=quickGames[game];let score=0,time=cfg.time,timer=null,running=true,target=cfg.icon;stage.innerHTML=`<div class="game-ui quick-game"><p class="eyebrow">NEW ARCADE CHALLENGE</p><h2>${cfg.title}</h2><div class="quick-hud"><b id="quickScore">0 / ${cfg.goal}</b><b id="quickTime">⏱ ${time}s</b></div><p id="quickMsg">${cfg.mode==='choose'?'Tap the item shown above.':'Catch the right targets and avoid the decoys!'}</p><div class="quick-board" id="quickBoard"></div></div>`;const board=$('#quickBoard');function stop(){running=false;clearInterval(timer)}function lose(){stop();gameCleanup=null;stage.innerHTML=`<div class="game-ui"><p class="eyebrow">TIME UP</p><h2>${cfg.title}</h2><p>You scored ${score} / ${cfg.goal}. Try again!</p><button class="primary" onclick="quickArcadeGame('${game}')">RETRY</button></div>`;beep(80,.25)}function point(){score++;beep(480+score*25);$('#quickScore').textContent=`${score} / ${cfg.goal}`;if(score>=cfg.goal){stop();gameCleanup=null;return bonusWin(game)}spawn()}function spawn(){if(!running)return;board.innerHTML='';if(cfg.mode==='choose'){target=cfg.icons[Math.floor(Math.random()*cfg.icons.length)];$('#quickMsg').textContent=`FIND ${target}`;[...cfg.icons].sort(()=>Math.random()-.5).forEach(icon=>{const b=document.createElement('button');b.className='quick-choice';b.textContent=icon;b.onclick=()=>{if(icon===target)point();else{time=Math.max(1,time-2);beep(90,.15)}};board.append(b)})}else{const icons=[cfg.icon,...cfg.decoys,...cfg.decoys];icons.forEach((icon,i)=>{const b=document.createElement('button');b.className='quick-target';b.textContent=icon;b.style.left=Math.random()*82+'%';b.style.top=Math.random()*72+'%';b.style.animationDelay=i*.08+'s';b.onclick=()=>{if(icon===cfg.icon)point();else{time=Math.max(1,time-2);b.remove();beep(90,.15)}};board.append(b)})}}timer=setInterval(()=>{time--;const el=$('#quickTime');if(el)el.textContent=`⏱ ${time}s`;if(time<=0)lose()},1000);gameCleanup=stop;spawn()}
renderCreatedGames();paintAvatar();paintOutfit();paintBackpack();renderClothes();renderPants();renderBackpacks();renderSweaters();populateListingDesigns();renderMarket();renderFriends();renderUpgrades();renderBackpack();
